{
  "id": "vuln-thrift-0919c3d5",
  "pattern": "socket.getSSLParameters();\n      socket.setSSLParameters(...)",
  "pattern_not": [
    "socket.getSSLParameters();\n      SSLParameters sslParams = socket.getSSLParameters();\n      sslParams.setEndpointIdentificationAlgorithm(\"HTTPS\");\n      socket.setSSLParameters(sslParams);"
  ],
  "languages": [
    "java"
  ],
  "message": "Missing endpoint identification algorithm configuration in SSL transport. This vulnerability allows for man-in-the-middle attacks as the client does not verify the server's identity. Fix by setting the endpoint identification algorithm to \"HTTPS\" using SSLParameters.setEndpointIdentificationAlgorithm().",
  "severity": "ERROR",
  "metadata": {
    "category": "security",
    "cwe": "CWE-295",
    "owasp": "OWASP-A03:2021"
  }
}

